def exponentiation_dichotomique(a, k):
    res = a
    ones = 1
    while (k > 1):
        if k % 2 == 0:
            res = res * res
            k = k // 2
        else:
            ones = ones * res
            res = res * res 
            k = k // 2
    return res * ones

exponentiation_dichotomique(2,8)

