class Dico:

    def __init__(self, init_size=30):
        self.container = [[] for _ in range(init_size)]

    def __setitem__(self, key, value):
        idx = self._get_idx(key)
        if key in self:
            del self[key]
        self.container[idx].append((key, value))

    def __getitem__(self, key):
        idx = self._get_idx(key)
        for k, v in self.container[idx]:
            if k == key:
                return v
        raise KeyError(key)

    def __delitem__(self, key):
        idx = self._get_idx(key)
        for i, (k, v) in enumerate(self.container[idx]):
            if k == key:
                del self.container[idx][i]
                return True
        raise KeyError(key)

    def __contains__(self, key):
        idx = self._get_idx(key)
        for k, v in self.container[idx]:
            if k == key:
                return True
        return False

    def _get_idx(self, key):
        return hash(key) % len(self.container)

    def keys(self):
        keys = []
        for cell in self.container:
            for k, _ in cell:
                keys.append(k)
        return keys

    def values(self):
        values = []
        for cell in self.container:
            for _, v in cell:
                values.append(v)
        return values

    def __repr__(self):
        return repr(self.container)
